begin;
alter table public.artigos
 add column seo_title text not null default '' check(char_length(seo_title)<=180),
 add column seo_description text not null default '' check(char_length(seo_description)<=320),
 add column keywords text[] not null default '{}',
 add column social_title text not null default '' check(char_length(social_title)<=180),
 add column social_description text not null default '' check(char_length(social_description)<=500),
 add column social_image_url text check(social_image_url is null or social_image_url ~ '^https://'),
 add column social_image_alt text not null default '',
 add column canonical_url text check(canonical_url is null or canonical_url ~ '^https://'),
 add column noindex boolean not null default false;

create policy editorial_media_insert on storage.objects for insert to authenticated with check (
 bucket_id='public-media' and (storage.foldername(name))[1]='editorial'
 and public.is_admin() and lower(storage.extension(name)) in ('jpg','jpeg','png','webp','avif')
 and (metadata->>'size')::bigint <= 5242880
);

-- Conteúdo editorial inicial: rascunhos, sem sobrescrever posts existentes.
insert into public.artigos (slug,title,category,excerpt,content_html,author_name,status,seo_title,seo_description,social_title,social_description,keywords) values ('como-organizar-seu-curriculo','Como organizar seu currículo para a próxima oportunidade','Carreira','Um roteiro para apresentar suas experiências com clareza e adaptar o currículo à oportunidade que você procura.','<p>Um bom currículo ajuda quem contrata a entender o que você sabe fazer. Ele não precisa contar toda a sua história: precisa mostrar as informações mais úteis para a oportunidade.</p><h2>Comece pelos contatos e pelo objetivo</h2><p>Confira nome, telefone e e-mail. Informe sua cidade e a área em que deseja trabalhar. Evite colocar documentos pessoais, endereço completo ou informações que não sejam necessárias nessa primeira apresentação.</p><h2>Mostre o que você fez</h2><p>Nas experiências, escreva a função, a organização, o período e as principais atividades. Prefira exemplos concretos: atendimento ao público, organização de estoque, preparo de alimentos ou apoio administrativo. Inclua resultados quando você conseguir descrevê-los com precisão, sem inventar números.</p><h2>E quando ainda não há experiência formal?</h2><p>Projetos escolares, trabalho voluntário, cursos e atividades por conta própria podem mostrar habilidades. Explique o que você fez e o que aprendeu. Evite listar qualidades genéricas sem exemplos.</p><h2>Adapte e revise</h2><ul><li>Leia os requisitos da vaga antes de enviar.</li><li>Destaque experiências relacionadas ao trabalho.</li><li>Confira datas, escrita e contatos.</li><li>Use um arquivo legível no celular e no computador.</li></ul><p>No EmpregaSantana, organize seus currículos no painel e escolha qual apresentar em cada candidatura. Depois, acompanhe as oportunidades em <a href="/explorar?tipo=vagas">Encontrar trabalho</a>.</p>','Equipe EmpregaSantana','draft','Como organizar seu currículo para a próxima oportunidade','Um roteiro para apresentar suas experiências com clareza e adaptar o currículo à oportunidade que você procura.','Como organizar seu currículo para a próxima oportunidade','Um roteiro para apresentar suas experiências com clareza e adaptar o currículo à oportunidade que você procura.',array['currículo','primeiro emprego','Santana do Ipanema']) on conflict(slug) do nothing;
insert into public.artigos (slug,title,category,excerpt,content_html,author_name,status,seo_title,seo_description,social_title,social_description,keywords) values ('como-apresentar-seu-servico','Seu serviço merece uma apresentação clara','Trabalho autônomo','Organize uma apresentação que explique o serviço, a região atendida e como você trabalha, sem depender apenas de indicação.','<p>Quem procura um profissional quer entender se ele atende à necessidade, trabalha na região e oferece um serviço compatível com o que precisa. Um perfil organizado facilita essa primeira conversa.</p><h2>Diga o que você faz</h2><p>Use um título específico. Em vez de apenas “serviços em geral”, explique sua especialidade. Na descrição, liste os principais trabalhos que realiza e também os limites do atendimento. Isso evita expectativas diferentes entre você e quem contrata.</p><h2>Mostre exemplos com cuidado</h2><p>Fotografias de trabalhos anteriores ajudam a apresentar sua experiência. Escolha imagens nítidas e explique o que foi realizado. Antes de publicar, peça autorização quando houver pessoas, imóveis ou informações de clientes identificáveis. Não divulgue documentos ou contatos de terceiros.</p><h2>Explique o atendimento</h2><ul><li>Informe a cidade e a região em que atende.</li><li>Explique se faz atendimento remoto ou no local.</li><li>Indique se cobra por hora, por entrega ou por orçamento.</li><li>Combine materiais, prazos e condições antes de iniciar.</li></ul><h2>Mantenha o perfil atualizado</h2><p>Revise seus serviços e sua disponibilidade. Um perfil simples e atual é mais útil que uma apresentação extensa com informações antigas. No EmpregaSantana, você pode divulgar seus serviços e também procurar oportunidades de trabalho usando a mesma conta.</p><p>Comece conhecendo a <a href="/explorar?tipo=autonomos">área de profissionais</a> e organize sua apresentação pelo painel.</p>','Equipe EmpregaSantana','draft','Seu serviço merece uma apresentação clara','Organize uma apresentação que explique o serviço, a região atendida e como você trabalha, sem depender apenas de indicação.','Seu serviço merece uma apresentação clara','Organize uma apresentação que explique o serviço, a região atendida e como você trabalha, sem depender apenas de indicação.',array['profissionais autônomos','serviços','portfólio']) on conflict(slug) do nothing;
insert into public.artigos (slug,title,category,excerpt,content_html,author_name,status,seo_title,seo_description,social_title,social_description,keywords) values ('como-escrever-uma-vaga-clara','Como escrever uma vaga que ajuda a encontrar a pessoa certa','Para empresas','Título, atividades, local e condições: informações que ajudam profissionais a avaliar uma oportunidade antes de se candidatar.','<p>Uma vaga clara facilita a decisão de quem procura trabalho e ajuda a empresa a receber candidaturas mais relacionadas à oportunidade. O primeiro passo é descrever o trabalho real, sem promessas que não podem ser cumpridas.</p><h2>Escolha um título específico</h2><p>Use o nome da função e evite expressões vagas ou exageradas. O título deve ser compreensível para quem ainda não conhece sua empresa.</p><h2>Separe atividades de requisitos</h2><p>Conte o que a pessoa fará no dia a dia. Depois, indique os conhecimentos necessários e diferencie requisitos essenciais de habilidades que podem ser aprendidas. Não copie uma lista extensa de exigências sem relação com a função.</p><h2>Explique as condições da oportunidade</h2><ul><li>Informe cidade, local de atuação e possibilidade de trabalho remoto.</li><li>Descreva jornada e forma de contratação.</li><li>Informe remuneração e benefícios quando puder divulgá-los.</li><li>Explique como funciona a candidatura e até quando ela será recebida.</li></ul><h2>Revise antes de publicar</h2><p>Confira se a descrição é respeitosa, objetiva e relacionada ao trabalho. Retire exigências pessoais que não tenham relação com a função. Revise também os contatos e os dados da empresa.</p><h2>Acompanhe e encerre</h2><p>Depois de publicar, reserve tempo para avaliar as candidaturas. Ao finalizar a seleção, atualize a situação da vaga para não manter uma oportunidade encerrada circulando no catálogo. A área da empresa no EmpregaSantana reúne publicação e acompanhamento das candidaturas.</p>','Equipe EmpregaSantana','draft','Como escrever uma vaga que ajuda a encontrar a pessoa certa','Título, atividades, local e condições: informações que ajudam profissionais a avaliar uma oportunidade antes de se candidatar.','Como escrever uma vaga que ajuda a encontrar a pessoa certa','Título, atividades, local e condições: informações que ajudam profissionais a avaliar uma oportunidade antes de se candidatar.',array['publicar vaga','contratação','empresas']) on conflict(slug) do nothing;
commit;
